public List<String> summaryRanges(int[] nums) {
    List<String> out = new ArrayList<>();
    int n = nums.length;
    for (int i = 0; i < n; ) {
        int j = i;
        while (j + 1 < n && (long) nums[j + 1] == (long) nums[j] + 1) j++;           // extend the run
        out.add(i == j ? String.valueOf(nums[i]) : nums[i] + "->" + nums[j]);
        i = j + 1;
    }
    return out;
}
